# Kaggle kernel for Stage A (audio embeddings). Generated by kaggle/build_embed.sh from src/embed.py.
import base64, glob, os, subprocess, sys, time
import torch
from huggingface_hub import snapshot_download

WHISPER, WAVLM, W2VBERT = "none", "none", "facebook/w2v-bert-2.0"
OUT = "/kaggle/working"
SCRIPT = "/tmp/embed.py"
open(SCRIPT, "w").write(base64.b64decode("").decode())
csv = glob.glob("/kaggle/input/**/train.csv", recursive=True)
assert csv, "competition data not attached"
DATA = os.path.dirname(csv[0])

# Download weights once, before the workers start, so two processes do not fetch the same files.
for m in (WHISPER, WAVLM, W2VBERT):
    if m == "none":
        continue
    snapshot_download(m, allow_patterns=["*.json", "*.safetensors", "*.txt"])

n = max(1, torch.cuda.device_count())
print("GPUs:", n, [torch.cuda.get_device_name(i) for i in range(n)] if torch.cuda.is_available() else "none", flush=True)
args = ["--data", DATA, "--out", OUT, "--whisper", WHISPER, "--wavlm", WAVLM, "--w2vbert", W2VBERT, "--nshards", str(n)]
t0 = time.time()
procs = [subprocess.Popen([sys.executable, SCRIPT, *args, "--shard", str(i)],
                          env={**os.environ, "CUDA_VISIBLE_DEVICES": str(i)}) for i in range(n)]
codes = [p.wait() for p in procs]
print("worker exit codes:", codes, "| wall time %.0f s" % (time.time() - t0), flush=True)
assert all(c == 0 for c in codes)
if n > 1:
    subprocess.run([sys.executable, SCRIPT, *args, "--merge"], check=True)
print(sorted(os.listdir(OUT)))
